t.script:
(function () {
    /* ── Config ──────────────────────────────────────────────── */
    const faceioEnabled = ;
    const appId         = "";

    /* ── Elements ────────────────────────────────────────────── */
    const kioskBtn   = document.getElementById("kiosk_btn");
    const btnIcon    = document.getElementById("kiosk_btn_icon");
    const btnLabel   = document.getElementById("kiosk_btn_label");
    const btnSpinner = document.getElementById("kiosk_spinner");
    const result     = document.getElementById("kiosk_result");
    const logBody    = document.getElementById("kiosk_log_body");
    const geoStatus  = document.getElementById("geo_status");

    /* ── Clock ───────────────────────────────────────────────── */
    (function tick() {
        const now = new Date();
        document.getElementById("k_clock").textContent =
            now.toLocaleTimeString([], {hour: "2-digit", minute: "2-digit", second: "2-digit"});
        document.getElementById("k_date").textContent =
            now.toLocaleDateString([], {weekday:"long", year:"numeric", month:"long", day:"numeric"});
        setTimeout(tick, 1000);
    })();

    /* ── Geolocation ─────────────────────────────────────────── */
    let geoLat = 0, geoLng = 0;
    if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(function(pos) {
            geoLat = pos.coords.latitude;
            geoLng = pos.coords.longitude;
            geoStatus.textContent = "Location: " + geoLat.toFixed(4) + ", " + geoLng.toFixed(4);
        }, function() {
            geoStatus.textContent = "Location: not available";
        });
    } else {
        geoStatus.textContent = "Location: not supported";
    }

    /* ── Loading state ───────────────────────────────────────── */
    function setLoading(yes) {
        kioskBtn.disabled     = yes;
        btnSpinner.style.display = yes ? "inline-block" : "none";
        btnIcon.style.display    = yes ? "none" : "inline";
        btnLabel.textContent     = yes ? "Reading face…" : "Scan My Face";
    }

    /* ── Show result ─────────────────────────────────────────── */
    function showResult(data) {
        result.className = "kiosk-result " + (data.action === "check_in" ? "checkin" : data.action === "check_out" ? "checkout" : "error");
        result.style.display = "block";

        const name = data.employee_name || "Unknown";
        document.getElementById("res_avatar").textContent = name.charAt(0).toUpperCase();
        document.getElementById("res_name").textContent   = name;
        document.getElementById("res_job").textContent    = data.employee_job || "";

        const badgeWrap = document.getElementById("res_badge_wrap");
        if (data.action === "check_in") {
            badgeWrap.innerHTML = ' Checked In';
        } else if (data.action === "check_out") {
            badgeWrap.innerHTML = ' Checked Out';
        } else {
            badgeWrap.innerHTML = ' Error';
        }

        const rows = document.getElementById("res_rows");
        rows.innerHTML = "";
        function addRow(label, value) {
            rows.innerHTML +=
                '' + label + '' +
                '' + (value || "—") + '';
        }

        if (data.action === "check_in") {
            addRow("Check-in",  formatDT(data.check_in));
        } else if (data.action === "check_out") {
            addRow("Check-in",    formatDT(data.check_in));
            addRow("Check-out",   formatDT(data.check_out));
            addRow("Hours worked", data.worked_hours || "—");
        } else {
            addRow("Error", data.message || "Unknown error");
        }
    }

    function showError(msg) {
        result.className = "kiosk-result error";
        result.style.display = "block";
        document.getElementById("res_avatar").textContent = "!";
        document.getElementById("res_name").textContent = "Error";
        document.getElementById("res_job").textContent = "";
        document.getElementById("res_badge_wrap").innerHTML =
            ' Failed';
        document.getElementById("res_rows").innerHTML =
            'Reason' +
            '' + msg + '';
    }

    /* ── Add log row ─────────────────────────────────────────── */
    function addLog(name, action, time) {
        const prev = logBody.querySelector("[data-placeholder]");
        if (prev) prev.remove();
        const dot  = action === "check_in" ? "dot-in" : "dot-out";
        const type = action === "check_in" ? "in"     : "out";
        const label= action === "check_in" ? "IN"     : "OUT";
        const row  = document.createElement("div");
        row.className = "kiosk-log-row";
        row.innerHTML =
            '' +
            '' + name + '' +
            '' + time + '' +
            '' + label + '';
        logBody.insertBefore(row, logBody.firstChild);
        // keep max 10 rows
        while (logBody.children.length > 10) logBody.removeChild(logBody.lastChild);
    }

    /* ── Helpers ─────────────────────────────────────────────── */
    function formatDT(dtStr) {
        if (!dtStr) return "—";
        const d = new Date(dtStr.replace(" ", "T") + "Z");
        return d.toLocaleTimeString([], {hour: "2-digit", minute: "2-digit"});
    }

    /* ── Kiosk scan ──────────────────────────────────────────── */
    if (!faceioEnabled || !appId) {
        kioskBtn.disabled = true;
        btnLabel.textContent = "FaceIO not configured";
        return;
    }

    const faceio = new faceIO(appId);

    let resetTimeout = null;

    kioskBtn.addEventListener("click", async function () {
        // Clear any pending reset
        if (resetTimeout) clearTimeout(resetTimeout);

        setLoading(true);
        result.style.display = "none";
        try {
            const userData = await faceio.authenticate({ locale: "auto" });
            const facialId = userData.facialId;

            const payload = {
                jsonrpc: "2.0", method: "call", id: Date.now(),
                params: {
                    facial_id:   facialId,
                    lat:         geoLat,
                    lng:         geoLng,
                    device_uuid: "faceio-kiosk",
                },
            };
            const response = await fetch("/hr_hub/faceio/kiosk/checkin", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(payload),
            });
            const data = await response.json();
            if (data.error) {
                const msg = (data.error.data && data.error.data.message)
                    ? data.error.data.message : data.error.message;
                showError(msg);
            } else {
                const res = data.result;
                showResult(res);
                addLog(res.employee_name, res.action, formatDT(res.action === "check_in" ? res.check_in : res.check_out));
            }
        } catch (err) {
            showError("Face scan failed: " + String(err));
        } finally {
            setLoading(false);
            try { faceio.restartSession(); } catch (e) {}

            // Auto-reset kiosk UI for next employee after 6 seconds
            resetTimeout = setTimeout(function() {
                result.style.display = "none";
            }, 6000);
        }
    });
})();
